SELECT id, product_id, unit_price, ROW_NUMBER() OVER w_grp AS event_seq, LAST_VALUE(quantity) IGNORE NULLS OVER w_part AS last_known_quantity, AVG(unit_price) OVER (PARTITION BY product_id, order_id ORDER BY quantity, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS unit_price_avg_6, NTILE(3) OVER w_hist AS unit_price_bucket, NTILE(5) OVER w_grp AS quantity_bucket FROM order_items WHERE product_id IS NOT NULL WINDOW w_grp AS (ORDER BY quantity DESC, id), w_part AS (PARTITION BY order_id ORDER BY quantity, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW), w_hist AS (PARTITION BY order_id ORDER BY unit_price, id);
